window.NW_WORKS=Object.assign(window.NW_WORKS||{}, {"eat":{"id":"eat","title":"%EAT","subtitle":"Natural Dog Food · Brand & Package Design","lead":"%EAT는 반려견에게 필요한 영양과 취향을 비율에 맞게 설계하는 맞춤형 자연식 브랜드입니다.","summary":"%EAT는 반려견을 위한 맞춤형 자연식 브랜드입니다. 우리는 반려견의 식사를 단순한 사료나 간식이 아니라, 보호자가 반려견의 건강과 취향, 생활 리듬을 세심하게 바라보는 하나의 돌봄 행위로 해석했습니다. 브랜드명 %EAT는 반려견에게 필요한 영양과 취향을 비율에 맞게 설계한다는 의미를 담고 있습니다. 먹는다는 가장 기본적","client":"%EAT","scope":"Brand System Package Design","category":"Natural Dog Food Pet Brand","role":"Brand Concept Graphic Direction","thumbnail":"https://cdn.imweb.me/upload/S2023030963558ef55ba8e/65b7ff1d94064.png","sections":[{"label":"Special Meal","title":"반려견의 한 끼를 더 특별한 경험으로 바라봤습니다","paragraphs":["%EAT는 단순히 반려견에게 먹을 것을 제공하는 브랜드가 아니라, 보호자가 반려견의 하루와 상태를 더 섬세하게 바라보게 만드는 브랜드입니다. 매일 반복되는 식사 안에서도 반려견의 컨디션, 기호, 나이, 생활 패턴을 고려할 수 있어야 한다고 보았고, 특히 BIRTHDAY SPECIAL과 같은 제품 라인은 반려견의 생일이나 기념일을 위한 특별식으로 기획해 보호자가 반려견에게 마음을 표현할 수 있"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/4ded401b4952d.png"]},{"label":"Pastel Pattern","title":"파스텔 컬러와 반려견 패턴으로 부드러운 프리미엄 무드를 만들었습니다","paragraphs":["%EAT의 시각 언어는 파스텔 컬러와 반려견 실루엣 패턴을 중심으로 구성되었습니다. 코랄, 블루, 크림 계열의 컬러는 자연식이 가진 부드럽고 건강한 인상을 전달하면서도 일반적인 펫푸드 패키지에서 보기 어려운 섬세한 분위기를 만들어냅니다. 패턴은 단순한 장식이 아니라 브랜드의 친근함을 보여주는 핵심 그래픽 자산으로, 반려견의 형태를 추상화해 반복적으로 배치함으로써 펫 브랜드의 정체성은 유지하되"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/06f0fc2244a24.png"]},{"label":"Label System","title":"라벨은 감성과 정보를 함께 담는 구조로 설계했습니다","paragraphs":["%EAT의 라벨은 제품의 성격과 정보를 동시에 전달하는 중요한 매체입니다. 자연식 제품은 원재료, 급여 정보, 영양 구성 등 정확한 정보 전달이 중요하기 때문에, 라벨 디자인은 감성적인 분위기만으로 완성될 수 없다고 판단했습니다. 우리는 라벨을 하나의 작은 문서처럼 바라보고, 제품명과 주요 정보는 명확하게 읽히도록 정돈하되 브랜드 로고와 반려견 그래픽은 상단에 배치해 첫인상을 부드럽게 만들었"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/fa8d3aedb0e02.png"]},{"label":"Trust & Gift","title":"자연식 브랜드의 신뢰감과 선물 같은 감정을 함께 담았습니다","paragraphs":["반려동물 식품은 보호자의 신뢰가 무엇보다 중요하지만, 신뢰를 너무 기능적으로만 표현하면 브랜드가 차갑고 딱딱해질 수 있습니다. %EAT는 그 사이의 균형을 찾고자 했습니다. 패키지는 스탠드 파우치 구조를 기반으로 실용성을 확보하고, 컬러와 라벨을 통해 제품별 개성을 부여했습니다. 큰 용량의 파우치는 안정감 있는 블루 계열로, 작은 파우치는 코랄 컬러로 구성해 제품의 용도와 크기에 따라 다른 "],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/bfd82afba63c6.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/79744b0f25847.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/752332507de90.png"]},{"label":"Archive Images","title":"Archive Images","paragraphs":["%EAT Brand Project는 반려견의 식사를 단순한 사료가 아니라 보호자의 세심한 돌봄 행위로 해석한 맞춤형 자연식 브랜드 디자인 작업입니다. 파스텔 컬러, 반려견 패턴, 정돈된 라벨 시스템, 선물 같은 패키지 경험을 통해 부드럽지만 신뢰감 있는 프리미엄 펫푸드 브랜드 이미지를 구축했습니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/1e663ddee8f1b.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/de663d0388b74.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/b74a17866f464.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/c9203d7d7b272.png"]}]},"breeze-coffee":{"id":"breeze-coffee","title":"Breeze Coffee","subtitle":"Urban Coffee Salon · Brand Design","lead":"Breeze Coffee는 장소의 기억과 커피의 향, 도시의 속도 사이에서 작게 쉬어갈 수 있는 커피 살롱 브랜드입니다.","summary":"Breeze Coffee Brand Project는 용산 열정도 거리의 오래된 구옥이 가진 시간의 결을 바탕으로, 도심 속에서 산들바람처럼 머무는 커피 경험을 제안하기 위해 기획된 커피 살롱 브랜드 디자인 프로젝트입니다. 브랜드는 커피를 단순한 음료가 아니라, 재개발의 경계와 고층 빌딩 사이에 남겨진 공간의 기억을 감각적","client":"Breeze Coffee","scope":"Brand System Package Design","category":"Urban Coffee Salon Café Brand","role":"Brand Concept Graphic Direction","thumbnail":"https://cdn.imweb.me/upload/S2023030963558ef55ba8e/5c12e36ae2396.png","sections":[{"label":"Place Memory","title":"도심의 골목 끝에서 시작된 커피 브랜드","paragraphs":["Breeze Coffee는 용산 열정도 거리의 오래된 구옥에서 출발한 커피 브랜드입니다. 우리는 이 공간이 단순히 새롭게 꾸며질 카페가 아니라, 과거의 흔적과 지금의 도시가 겹쳐진 장소라고 보았습니다. 재개발의 경계와 고층 빌딩 사이에 남겨진 구옥은 브리즈커피가 지향하는 감정적 출발점이 되었고, 브랜드는 그 시간의 결을 지우기보다 얇게 덧입히는 방식으로 설계되었습니다. 이전에 두유 가게였던 "],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/607e7f21668a5.png"]},{"label":"Visual Identity","title":"바람과 향의 흐름을 담은 브랜드 아이덴티티","paragraphs":["Breeze Coffee의 아이덴티티는 바람의 움직임과 커피 향의 흐름에서 출발했습니다. 커피는 한 잔의 음료로 소비되지만, 그 향은 공간을 가볍게 채우고 사람의 감각을 천천히 움직입니다. 우리는 이 흐름을 브랜드의 시각 언어로 번역하기 위해 열기구, 구름, 산, 도시의 실루엣 같은 그래픽 요소를 사용했습니다. 열기구는 바람을 타고 이동하는 이미지이자, 일상에서 잠시 벗어나는 작은 여행의 은"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/ac19bd5232dfd.jpeg","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/2ea690fd3c260.jpeg","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/3b448e752f059.png"]},{"label":"Color System","title":"웜 브라운과 버건디로 완성한 커피 살롱 무드","paragraphs":["Breeze Coffee의 시각 시스템은 웜 브라운과 버건디 컬러를 중심으로 구성되었습니다. 웜 브라운은 오래된 나무 벽, 햇빛에 바랜 가구, 황동 손잡이, 커피가 남기는 따뜻한 온도를 떠올리게 하며 브랜드의 기본 정서를 형성합니다. 버건디는 공간에 깊이와 클래식한 분위기를 더하고, 브랜드가 지나치게 밝거나 가볍게 보이지 않도록 무게를 잡아줍니다. 패키지에 사용된 크림톤과 브라운 계열의 일러"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/609a2735d8382.jpeg"]},{"label":"Package System","title":"공간의 기억을 이어가는 패키지와 그래픽 시스템","paragraphs":["Breeze Coffee의 패키지와 그래픽 시스템은 공간이 가진 이야기와 커피의 감각을 함께 전달하도록 구성되었습니다. 컵 슬리브와 포장재에는 열기구, 산, 구름, 밤의 도시 같은 장면을 적용해, 커피 한 잔이 작은 풍경처럼 느껴지도록 했습니다. 낮의 패키지는 밝은 크림과 브라운 톤으로 따뜻하고 부드러운 인상을 주고, 밤의 패키지는 버건디와 어두운 도시 실루엣을 통해 더 깊고 조용한 분위기를"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/2dfed9c3fc9a1.png"]},{"label":"Salon Experience","title":"커피 한 잔보다 먼저 감정을 따라가는 브랜드 경험","paragraphs":["Breeze Coffee가 제안하는 경험은 좋은 원두와 추출을 넘어, 한 사람이 공간에 들어와 머물고 다시 나가는 전체 흐름 안에서 완성됩니다. 우리는 바닥의 질감, 유리창 너머의 빛, 메뉴보드의 시선, 의자의 높이, 커피 향이 퍼지는 방향까지 브랜드 경험의 일부로 보았습니다. 공간은 너무 빠르거나 화려하게 소비되지 않고, 도심 속에서 잠시 속도를 늦출 수 있는 완충지대처럼 작동하도록 설계되"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/9633455e97e7c.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/ddc4e8ff4d43b.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/a1d73918d0664.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/08e03bbb93e52.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/1dd3c179d7ea3.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/aab1e072709f1.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/68fe5a79a06dd.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/ae4e10f9b6606.png"]}]},"dev-coffee":{"id":"dev-coffee","title":"DEV COFFEE","subtitle":"Developer-Inspired · Specialty Coffee Brand Design","lead":"Dev Coffee는 일상의 집중력을 정직하게 설계하는 스페셜티 커피 브랜드입니다.","summary":"Dev Coffee Brand Project는 커피를 감성적 취향이 아니라, 집중과 기록, 반복 실험을 통해 완성되는 일상의 도구로 재해석하기 위해 기획된 스페셜티 커피 브랜드 디자인 프로젝트입니다. 브랜드명 Dev는 Development의 약어로, 개발과 개선, 탐구와 실험의 과정을 상징하며 커피를 만드는 사람의 집요한","client":"Dev Coffee","scope":"Brand System Package Design","category":"Specialty Coffee Lifestyle Brand","role":"Brand Concept Graphic Direction","thumbnail":"https://cdn.imweb.me/upload/S2023030963558ef55ba8e/3fede74ccfb4f.png","sections":[{"label":"Brand Attitude","title":"집중력과 집요함에서 출발한 커피 브랜드","paragraphs":["Dev Coffee는 커피를 단순히 맛과 향으로 소비하는 브랜드가 아니라, 커피를 대하는 태도와 과정에서 출발한 브랜드입니다. 우리는 이 브랜드를 ‘개발자가 만든 커피’라는 표면적인 설명에 가두지 않고, 개발자적 사고방식이 가진 반복, 기록, 개선, 몰입의 감각으로 재구성하고자 했습니다. Dev라는 이름은 Development의 약어이자, 끝없이 테스트하고 고쳐가며 더 나은 결과를 만드는 사"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/0dbcda5c855b1.png"]},{"label":"Visual Identity","title":"개발자적 감각을 담은 시각 아이덴티티","paragraphs":["Dev Coffee의 시각 아이덴티티는 기능과 목적에 충실한 간결한 구조를 기반으로 설계되었습니다. 블랙과 그레이, 오프화이트의 기본 조합은 개발 환경의 다크모드와 터미널 화면, 코드 편집기의 정리된 긴장감을 연상시키며 브랜드의 전문성을 만듭니다. 여기에 브랜드 그린 계열을 포인트로 사용해 차갑고 기술적인 인상 안에서도 커피가 가진 생동감과 리듬을 잃지 않도록 조율했습니다. 로고는 고정폭 폰"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/dbfe526cf3080.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/db352274da3d9.png"]},{"label":"Daily Routine","title":"생각하는 사람들을 위한 일상의 루틴","paragraphs":["Dev Coffee는 개발자만을 위한 커피가 아니라, 매일 스스로의 리듬을 설계해야 하는 모든 사람을 위한 브랜드입니다. 생각이 많은 사람, 기록을 반복하는 사람, 오랜 시간 집중해야 하는 사람, 의미 없어 보이는 루틴을 성실하게 이어가는 사람들에게 Dev Coffee는 하나의 일상적 도구로 작동합니다. 우리는 이 브랜드가 특정 직군의 취향을 좁게 대변하기보다, 집중과 몰입이 필요한 사람들의"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/4fa0eb2a07e64.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/2cd89e51768ed.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/0a4491e5b13b9.png"]},{"label":"Package System","title":"감성보다 구조를 앞세운 패키지 시스템","paragraphs":["Dev Coffee의 패키지는 감성적인 커피 브랜드의 포장 방식보다, 연구실의 키트나 기록 도구처럼 보이는 구조를 지향했습니다. 우리는 커피가 단순히 예쁜 패키지 안에 담긴 제품이 아니라, 매일의 집중을 돕는 시스템처럼 느껴지기를 바랐습니다. 블렌딩 네임과 제품 정보는 문학적 표현보다 기능 기반의 라벨로 정리되었고, 커핑 노트 역시 추상적 감상보다는 수치와 인상, 기록의 언어에 가깝게 구성되"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/bf70630d6ff13.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/69d5068f59b4c.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/3a541a16a872a.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/30edd5301bb18.png"]},{"label":"Brand Message","title":"정직하게 설계된 일상의 도구","paragraphs":["Dev Coffee가 최종적으로 제안하는 것은 감각적인 커피 한 잔이 아니라, 매일의 집중을 돕는 정직한 도구로서의 커피입니다. 우리는 커피가 기분 좋은 향과 맛을 제공하는 동시에, 사용자의 하루를 조금 더 정리된 상태로 만들어줄 수 있다고 보았습니다. 품질, 로스팅 정확도, 패키지 정보, 브랜드 톤, 공간 이미지까지 모든 요소는 감정을 과하게 자극하기보다 생각을 선명하게 만드는 방향으로 정"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/b5471d31a7109.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/9e2ae1a7383a9.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/2f143b5f96fef.png"]},{"label":"Archive Images","title":"Archive Images","paragraphs":["Dev Coffee Brand Project는 커피를 감성적 취향이 아니라 집중과 기록, 반복 실험으로 완성되는 일상의 도구로 재해석한 스페셜티 커피 브랜딩 작업입니다. 블랙과 그레이, 오프화이트, 브랜드 그린을 중심으로 개발자적 긴장감과 커피의 생동감을 함께 담아낸 시각 시스템을 구축했습니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/080f0d078b0ab.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/c657431dc087d.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/99b0b4a7a1674.png"]}]},"helibean":{"id":"helibean","title":"HELI BEAN","subtitle":"Roasted Coffee Bean · Package Design","lead":"HELIBEAN은 로스팅된 원두의 성격과 산지의 이미지를 함께 설명하는 커피 브랜드입니다.","summary":"HELIBEAN은 원두가 가진 본질적인 정보와 맛의 인상을 직관적으로 전달하는 커피 브랜드입니다. 우리는 이 브랜드를 단순히 원두를 판매하는 패키지가 아니라, 로스팅된 원두의 성격과 산지의 이미지를 함께 설명하는 커피 브랜드로 해석했습니다. 특히 소비자가 원두를 선택할 때 가장 먼저 접하는 것은 패키지이기 때문에, 복잡한","client":"HELIBEAN","scope":"Package Design Brand System","category":"Roasted Coffee Bean Package","role":"Brand Concept Graphic Direction","thumbnail":"https://cdn.imweb.me/upload/S2023030963558ef55ba8e/4ae03c67c4d07.png","sections":[{"label":"Origin Story","title":"산지의 정보를 하나의 풍경처럼 보여주는 패키지","paragraphs":["HELIBEAN의 패키지는 원두의 산지와 맛의 특징을 하나의 작은 풍경처럼 보여주는 방식으로 설계되었습니다. 커피 패키지는 원산지, 로스팅 포인트, 향미 정보 등 전달해야 하는 요소가 많지만, 정보가 복잡해질수록 소비자가 제품의 성격을 직관적으로 이해하기 어려워질 수 있습니다. 우리는 패키지 전면에서 산지를 상징하는 이미지와 컬러를 먼저 보여주고, 상세한 정보는 규칙적인 구조 안에서 정돈했습니다. 이를 통해 소비자는"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/81e57f220d90a.png"]},{"label":"Color Coding","title":"컬러는 원두의 성격을 구분하는 가장 빠른 언어가 되었습니다","paragraphs":["HELIBEAN의 제품 시스템은 컬러 코딩을 통해 원두별 차이를 직관적으로 구분할 수 있도록 구성되었습니다. 밝은 오렌지와 옐로우 계열은 산뜻하고 과일향이 느껴지는 원두를, 짙은 브라운과 블루 계열은 깊고 무게감 있는 풍미를 연상시키도록 설계했습니다. 컬러는 단순한 장식이 아니라 소비자가 제품을 선택할 때 첫 번째로 인지하는 정보로 기능합니다. 동일한 레이아웃 안에서 컬러만 바뀌어도 원두의 성격이 구분되도록"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/cf6a4c28196f8.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/78eb97c889957.png"]},{"label":"Information System","title":"원두 정보는 명확하고 빠르게 읽히도록 정리했습니다","paragraphs":["커피 제품은 산지, 가공 방식, 로스팅 정도, 향미 노트처럼 다양한 정보를 제공해야 합니다. HELIBEAN은 이러한 정보를 복잡하게 나열하기보다 우선순위를 정해 계층적으로 배치했습니다. 제품명과 산지는 가장 먼저 읽히도록 크기를 키우고, 세부 정보는 작은 타이포그래피와 아이콘을 활용해 정돈했습니다. 소비자가 패키지를 손에 들었을 때 필요한 정보를 짧은 시간 안에 확인할 수 있도록 하는 것이 중요했습니다. 정보가 많더라도 전체적인"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/69e3e19714ead.png"]},{"label":"Brand Experience","title":"패키지에서 시작한 브랜드 경험을 공간과 콘텐츠로 확장했습니다","paragraphs":["HELIBEAN의 패키지 디자인은 온라인 콘텐츠와 오프라인 판매 환경에서도 동일한 인상을 유지할 수 있도록 확장되었습니다. 제품 촬영에서는 패키지 컬러와 원두의 질감이 함께 보이도록 연출하고, SNS 콘텐츠는 컬러 코딩 시스템을 활용해 제품별 특징을 빠르게 전달할 수 있도록 구성했습니다. 매대에서는 다양한 원두 제품이 나란히 놓였을 때 하나의 시리즈처럼 보이도록 패키지의 비례와 정보 위치를 통일했습니다. 이러한 시스템을 통해 소비자는"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/67a1339386d93.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/bd2562ae95a8f.png"]}]},"mayer":{"id":"mayer","title":"MAYER","subtitle":"Lifestyle Layering · Brand Design","lead":"MAYER는 매일 반복되는 생활 속 작은 감각을 기록하는 라이프스타일 브랜드입니다.","summary":"MAYER는 매일 반복되는 일상 속에서 스쳐 지나가는 좋은 감정들을 모아, 그것을 레이어처럼 차곡차곡 쌓아 기록할 수 있도록 설계한 라이프스타일 브랜드입니다. 우리는 일상을 특별한 사건의 연속이 아니라, 아주 작은 감각들이 반복되며 만들어지는 감정의 층으로 바라보았습니다. 마예르가 다루는 제품은 섬유유연제, 세탁세제, 디터전","client":"MAYER","scope":"Brand System Package Design","category":"Lifestyle Goods Fabric Care","role":"Brand Concept Graphic Direction","thumbnail":"https://cdn.imweb.me/upload/S2023030963558ef55ba8e/b61c21c37ebe8.png","sections":[{"label":"Emotion Archive","title":"감정은 지나가지만 기록은 오래 머뭅니다","paragraphs":["마예르는 일상에서 쉽게 사라지는 감정을 붙잡는 브랜드입니다. 좋은 향, 부드러운 촉감, 정돈된 공간의 분위기는 오래 머물지 않지만, 우리는 그것이 하루의 기분을 바꾸는 중요한 요소라고 보았습니다. 마예르의 브랜딩은 바로 그 짧은 감정의 순간을 시각적으로 기록하는 일에서 출발했습니다. 브랜드는 사용자의 삶을 과하게 바꾸겠다고 말하지 않습니다. 대신 이미 반복되고 있는 일상의 장면 안에 조용히 스며듭니다. 빨래를 개는 시간, 수건을 정리하는 순간, 침구를 바꾸는 저녁처럼 누구에게나 익숙한 행위 속에서 작은 만족감이 생길 수 있도록 브랜드의 감정선을 설계했습니다. 마예르가 추구하는 라이프스타일은 화려함보다 안정감에 가깝습니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/ff6be387a537d.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/4b0f7ea3f367b.png"]},{"label":"Visual Layer","title":"컬러보다 깊고, 형태보다 느린 감정의 레이어를 만들었습니다","paragraphs":["마예르의 시각 언어는 강한 인상을 남기기보다 일상 속에 조용히 머무르는 방식으로 설계되었습니다. 톤다운된 컬러와 부드러운 여백, 반복되는 레이어 구조를 통해 제품이 생활 공간 안에서 자연스럽게 어우러지도록 했습니다. 그래픽은 한 번에 설명되는 상징보다 여러 요소가 겹치고 쌓이는 방식으로 구성해 브랜드가 말하는 ‘좋은 감정의 축적’을 시각적으로 보여줍니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/cf33d3e9cd734.png"]},{"label":"Lifestyle State","title":"제품을 사용하는 순간의 상태를 브랜드로 연결했습니다","paragraphs":["마예르는 세탁, 정리, 향, 촉감처럼 일상적인 행동이 남기는 감정에 주목했습니다. 제품을 사용하는 순간마다 같은 언어와 분위기가 이어지도록 패키지와 콘텐츠, 촬영 무드를 하나의 톤으로 맞췄고, 각 제품이 독립적으로 보이기보다 하나의 생활 시스템 안에 놓이도록 구성했습니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/35e7860469760.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/1689034e5a138.png"]},{"label":"Brand Record","title":"생활의 작은 장면을 기록하는 브랜드 아카이브","paragraphs":["마예르는 캠페인 비주얼과 패키지, 인쇄물에서도 동일한 시각 기준을 유지해 브랜드의 기억이 여러 접점에서 이어지도록 했습니다. 정돈된 여백과 낮은 채도, 섬세한 타이포그래피를 통해 제품보다 그 제품이 놓이는 생활의 장면을 함께 보여주는 방식으로 확장했습니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/18cf2f14513ff.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/5fe8510bcdf92.png"]},{"label":"Archive Images","title":"Archive Images","paragraphs":["MAYER Brand Project는 일상의 작은 감각과 감정을 레이어처럼 차곡차곡 쌓는 라이프스타일 브랜드 디자인 프로젝트입니다. 제품 기능보다 사용 순간의 온도와 상태를 중심으로 시각 시스템을 설계해 조용하고 오래 머무는 브랜드 인상을 만들었습니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/2c17684cbf6d5.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/dc74632a54a37.png"]}]},"myv":{"id":"myv","title":"MYV","subtitle":"Value Consumption · Platform Brand Design","lead":"MYV는 소비자와 중소기업을 연결해 구매를 새로운 가치의 순환으로 만드는 플랫폼 브랜드입니다.","summary":"MYV Brand Project는 제품 구매를 단순한 소비가 아니라, 소비자와 중소기업이 함께 가치를 만들고 나누는 관계로 재해석한 플랫폼 브랜드 디자인 프로젝트입니다. 사용자는 검증된 제품을 경험하고 자신의 언어로 가치를 공유하며, 기업은 실제 소비자 반응을 통해 제품과 커뮤니케이션을 개선할 수 있도록 구조를 설계했습니다.","client":"MYV","scope":"Brand Design Platform Identity","category":"Value Consumption Platform","role":"Brand Concept Graphic Direction","thumbnail":"https://cdn.imweb.me/upload/S2023030963558ef55ba8e/13cc2b150bb03.png","sections":[{"label":"Brand Concept","title":"소비를 관계와 가치의 순환으로 바라봤습니다","paragraphs":["MYV는 소비자가 단순히 제품을 구매하는 사람을 넘어, 제품의 가치를 직접 경험하고 공유하는 참여자가 되도록 설계된 플랫폼입니다. 기업은 소비자의 실제 반응을 얻고, 소비자는 자신의 선택이 더 나은 제품과 서비스로 이어지는 과정을 경험하게 됩니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/3162378ea7993.png"]},{"label":"Visual System","title":"명확한 블루와 연결의 리듬으로 플랫폼의 신뢰를 만들었습니다","paragraphs":["MYV의 시각 시스템은 선명한 블루 컬러를 중심으로 구성되었습니다. 이 블루는 플랫폼 브랜드가 가져야 할 신뢰감과 기술적 명확성을 전달하면서도, 지나치게 차갑거나 딱딱하게 느껴지지 않도록 밝고 열린 톤으로 설정되었습니다. 로고는 부드러운 곡선과 연결되는 리듬을 가진 형태로, 소비자와 중소기업, 제품과 경험이 이어지는 플랫폼의 구조를 상징합니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/5739a4ceac991.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/2bd329eb003f0.jpeg","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/c022a6fa3acb3.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/a4b2d1e3ec0f4.png"]},{"label":"Service Experience","title":"중소기업과 소비자를 연결하는 서비스 경험","paragraphs":["MYV의 서비스 경험은 제품을 보여주고 구매하게 만드는 일반적인 커머스 구조와 다르게 설계되었습니다. 사용자는 플랫폼 안에서 검증된 제품을 발견하고, 직접 경험한 뒤, 자신의 언어로 제품의 가치를 전달하는 역할을 하게 됩니다. 이 과정에서 소비자는 단순한 고객이 아니라 콘텐츠 생성자이자 브랜드 파트너로 기능하며, 기업은 소비자의 실제 반응을 통해 제품과 커뮤니케이션을 개선할 수 있습니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/fa03fe36d0edf.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/00a2168401a82.png"]},{"label":"Archive Images","title":"Archive Images","paragraphs":["MYV Brand Project는 소비자와 중소기업, 제품과 경험, 구매와 가치를 연결하는 가치소비 플랫폼 브랜드 디자인입니다. 선명한 MYV 블루와 명확한 정보 구조, 관계 중심의 서비스 비주얼을 통해 소비가 새로운 가치의 순환으로 이어지는 브랜드 경험을 제안했습니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/87c86349ec372.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/b2907969a0b6f.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/f2e4562c94180.png"]}]},"pour-and-bake":{"id":"pour-and-bake","title":"POUR AND BAKE","subtitle":"Coffee & Bakery · Visual Identity Design","lead":"POUR AND BAKE는 커피와 베이커리의 감각을 컬러와 패턴으로 확장한 카페 브랜드입니다.","summary":"POUR AND BAKE는 커피와 베이커리의 경계를 따뜻하고 다채롭게 넘나드는 카페 브랜드입니다. 브랜드명은 커피를 따르는 행위인 “Pour”와 빵과 디저트를 굽는 행위인 “Bake”를 결합해, 한 공간 안에서 커피의 향과 베이커리의 온기가 자연스럽게 이어지는 경험을 담고 있습니다. 이번 프로젝트에서 우리는 커피를 단순히","client":"POUR AND BAKE","scope":"Visual Identity Package Design","category":"Coffee & Bakery Café Brand","role":"Brand Concept Graphic Direction","thumbnail":"https://cdn.imweb.me/upload/S2023030963558ef55ba8e/5430ed49b4326.png","sections":[{"label":"Brand Concept","title":"커피와 베이커리 사이의 감각을 브랜드 언어로 만들었습니다","paragraphs":["POUR AND BAKE는 커피만을 강조하는 브랜드도, 베이커리만을 앞세우는 브랜드도 아닙니다. 이 브랜드의 핵심은 두 감각이 함께 놓였을 때 만들어지는 여유로운 장면에 있습니다. 따뜻한 커피를 따르는 순간, 갓 구운 디저트를 고르는 순간, 테이블 위에 컵과 도넛이 함께 놓이는 장면은 모두 POUR AND BAKE가 제안하는 브랜드 경험입니다. 우리는 이 브랜드가 전문적인 커피 브랜드처럼 어"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/bfb9e177a6d4a.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/f40670a68322f.png"]},{"label":"Taste Pattern","title":"맛의 흐름을 컬러와 패턴으로 시각화했습니다","paragraphs":["POUR AND BAKE의 핵심 시각 자산은 비정형적인 컬러 패턴입니다. 이 패턴은 단순한 장식 요소가 아니라, 커피와 베이커리가 가진 맛의 층위를 시각적으로 표현한 장치입니다. 둥글게 흐르는 형태는 커피의 향이 퍼지는 움직임을 닮았고, 서로 겹쳐지는 컬러 블록은 산미, 단맛, 바디감, 잔향이 입 안에서 섞이는 감각을 상징합니다. 블루, 핑크, 오렌지, 브라운 계열의 컬러는 각각 산뜻함, 달"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/c2b9f5b4add0c.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/4d21f9fa4e08e.png"]},{"label":"Package System","title":"패키지는 브랜드를 가장 가까이 경험하는 매체가 되었습니다","paragraphs":["POUR AND BAKE의 테이크아웃 컵은 단순한 포장재가 아니라 브랜드의 첫인상을 전달하는 중요한 매체로 설계되었습니다. 손에 쥐는 컵 위에 브랜드 패턴이 크게 적용되면서, 사용자는 커피를 마시는 동안 자연스럽게 브랜드의 감각을 경험하게 됩니다. 컵의 상단에는 작은 라벨 형태의 정보 영역을 배치해 브랜드명과 제품 설명이 정돈되어 보이도록 했습니다. 전체 그래픽은 자유롭지만, 정보 영역은 차"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/befb7c0e4e7db.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/26af73ad892c4.png"]},{"label":"Visual Experience","title":"커피를 설명하는 새로운 방식이 필요했습니다","paragraphs":["많은 커피 브랜드는 맛을 전문적인 단어로 설명합니다. 산미, 바디감, 로스팅, 블렌딩, 원산지 같은 언어는 중요하지만, 모든 소비자가 그 언어를 직관적으로 이해하는 것은 아닙니다. 우리는 POUR AND BAKE가 커피의 맛을 조금 더 쉽고 감각적으로 전달하는 브랜드가 되기를 바랐습니다. 그래서 맛을 설명하는 방식도 기술적인 언어보다 이미지와 분위기 중심으로 정리했습니다. 컵의 컬러, 패턴의"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/91f284f94eddc.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/c1f44dde62db3.jpeg"]}]},"the-spa":{"id":"the-spa","title":"THE SPA","subtitle":"Premium Filtered Shower · & Bath Care Brand Design","lead":"THE SPA는 욕실의 일상적인 루틴을 프리미엄한 자기 돌봄 경험으로 확장한 필터 샤워 앤 배스 케어 브랜드입니다.","summary":"THE SPA Brand Project는 매일 반복되는 입욕과 샤워의 시간을 단순한 세정 행위가 아니라, 나를 위한 작은 휴식과 회복의 순간으로 재정의하기 위해 기획된 프리미엄 배스 케어 브랜드 디자인 프로젝트입니다. 브랜드는 필터 샤워기, 리필 필터, 퍼퓸 필터, 바디 케어 제품을 중심으로 욕실 안에서 경험할 수 있는 ","client":"THE SPA","scope":"Brand Design Package System","category":"Bath Care Filtered Shower","role":"Brand Concept Graphic Direction","thumbnail":"https://cdn.imweb.me/upload/S2023030963558ef55ba8e/082e2499b6add.png","sections":[{"label":"Rest Ritual","title":"나를 위한 작은 휴식을 제안하는 배스 케어 브랜드","paragraphs":["THE SPA는 매일 반복되는 샤워와 입욕의 시간을 조금 더 특별한 휴식의 순간으로 바꾸기 위해 출발한 배스 케어 브랜드입니다. 욕실에서의 시간은 단순히 몸을 씻는 기능적 행위에 머무르지 않고, 하루의 긴장을 내려놓고 다시 자신에게 돌아오는 조용한 의식이 될 수 있습니다. 브랜드는 화려한 스파 공간을 말하기보다, 집 안에서 누구나 경험할 수 있는 작고 현실적인 휴식을 제안합니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/31244c3dcf431.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/6529e59aff332.png"]},{"label":"Logo Identity","title":"청결함과 우아함을 담은 로고 아이덴티티","paragraphs":["THE SPA의 로고는 클래식한 세리프 타이포그래피를 기반으로 구성되었습니다. 세로로 정돈된 글자의 구조는 스파 브랜드가 가진 우아함과 정제된 분위기를 전달하며, 동시에 제품 패키지와 욕실 공간 안에서 명확하게 인식될 수 있는 안정감을 만듭니다. 얇고 긴 획의 리듬은 물줄기의 흐름과 욕실의 고요한 공기를 연상시키며, 브랜드가 지향하는 깨끗하고 섬세한 감각을 시각적으로 표현합니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/2b8ee0b871ed2.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/3a1f633c00494.png"]},{"label":"Product System","title":"필터 샤워기를 중심으로 확장되는 제품 경험","paragraphs":["THE SPA는 필터 샤워기를 중심으로 리필 필터, 퍼퓸 필터, 미네랄 필터, 바디 케어 제품까지 확장되는 배스 케어 시스템으로 설계되었습니다. 샤워기 헤드의 투명한 구조와 실버 마감은 물이 걸러지는 과정을 직관적으로 보여주며, 제품에 대한 신뢰감을 만듭니다. 사용자는 제품을 설치하고 물을 틀고 향과 촉감을 경험하는 과정에서 더스파의 브랜드 감각을 자연스럽게 느끼게 됩니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/c1dee95024472.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/83b7643b2df96.jpeg","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/69c9919416552.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/5c4493d8f379f.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/1dfe6606668a6.png"]},{"label":"Archive Images","title":"Archive Images","paragraphs":["THE SPA Brand Project는 욕실의 일상적인 루틴을 프리미엄한 자기 돌봄의 경험으로 확장한 배스 케어 브랜드 디자인입니다. 화이트와 실버 중심의 깨끗한 시각 시스템, 클래식한 로고, 필터 샤워기와 바디 케어 제품군을 통해 매일의 샤워를 조용한 휴식의 시간으로 제안했습니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/2134d5c9f4ded.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/1e9a6abe2d0db.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/8af480f08a9f9.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/ac8ac560d0238.png"]}]},"wiggly-yum":{"id":"wiggly-yum","title":"WIGGLY YUM","subtitle":"Kids Jelly Snack · Brand Design","lead":"WIGGLY YUM은 말랑한 식감과 밝은 컬러로 아이의 감정을 움직이는 키즈 젤리 스낵 브랜드입니다.","summary":"WIGGLY YUM은 아이가 한 입 베어 물었을 때 나타나는 표정, 웃음, 놀라움, 장난스러운 반응에서 출발한 키즈 젤리 스낵 브랜드입니다. 우리는 이 브랜드를 단순히 맛있는 간식이 아니라, 아이의 감정을 움직이는 작은 놀이 경험으로 바라보았습니다. 사과를 기반으로 한 상큼한 맛, 말랑하게 흔들리는 젤리의 물성, 손에 들","client":"WIGGLY YUM","scope":"Brand System Package Design","category":"Kids Snack Jelly Brand","role":"Brand Concept Graphic Direction","thumbnail":"https://cdn.imweb.me/upload/S2023030963558ef55ba8e/18d980f1614fa.png","sections":[{"label":"Expression Concept","title":"아이의 표정에서 브랜드가 시작되었습니다","paragraphs":["위글리염은 단지 맛있는 유아 간식을 만드는 브랜드가 아닙니다. 우리는 아이가 한 입 베어 물었을 때 보이는 표정, 웃음인지 놀람인지 모를 그 미세한 감정의 떨림을 브랜드의 출발점으로 삼았습니다. 아이는 맛으로만 반응하지 않습니다. 처음 만나는 질감, 흐르는 향, 손에 잡히는 패키지, 입 안에서 느껴지는 말랑한 변화, 혀끝에 닿는 온도까지 모두 감정으로 작용하기 "],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/01e9c903a23cd.png"]},{"label":"Texture Experience","title":"식감은 맛보다 먼저 감정을 움직이는 언어입니다","paragraphs":["우리는 먹는다는 행위가 단지 포만감을 위한 기능이 아니라 감정의 출입구라는 전제로 WIGGLY YUM을 기획했습니다. 특히 아이의 식경험은 단순한 섭취가 아니라 세계와의 접촉이라는 점에서, 위글리염은 맛보다 먼저 질감과 구조를 중심으로 제품을 개발했습니다. 아이가 한입 베어 물었을 때, 씹히는 속도, 흘러나오는 과즙감, 입안에서 미끄러지는 시간, 혀끝에 닿는 온도까지 모두 감정으로 작용하기 "],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/fe2ab1f99c981.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/cb0fea8252dfe.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/89b893521f418.jpeg"]},{"label":"Color System","title":"빨강과 라임의 대비로 브랜드의 생동감을 만들었습니다","paragraphs":["WIGGLY YUM의 시각 시스템은 레드와 라임 컬러의 강한 대비를 중심으로 구성되었습니다. 레드는 사과의 상큼함과 브랜드의 에너지를 직접적으로 보여주는 색이며, 라임은 젤리 특유의 말랑하고 튀는 감각을 더해주는 포인트 컬러로 작동합니다. 두 컬러는 키즈 브랜드에서 흔히 보이는 파스텔 중심의 부드러운 톤과 달리, 더 선명하고 즉각적인 반응을 만드는 방향으로 사용되었습니다. 로고는 굵고 둥근 "],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/fdc2f5a524e0a.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/793430f16222c.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/b5b0b323400b0.png"]},{"label":"Package Play","title":"패키지는 아이가 직접 경험하는 작은 놀이 도구입니다","paragraphs":["WIGGLY YUM의 패키지는 제품을 담는 용기 이상의 역할을 하도록 설계되었습니다. 아이가 손에 쥐고, 바라보고, 흔들고, 꺼내 먹는 일련의 과정이 브랜드 경험이 되기 때문입니다. 우리는 패키지가 너무 설명적이거나 보호자 중심으로 보이지 않도록 하고, 아이가 직관적으로 흥미를 느낄 수 있는 구조와 색감을 우선했습니다. 스틱형 젤리 패키지는 손에 들기 쉽고, 이동 중에도 먹기 편하며, 한 번"],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/05bdc7d8da61c.png"]},{"label":"Brand Message","title":"WIGGLY YUM은 먹는 순간을 웃음으로 바꾸는 브랜드입니다","paragraphs":["WIGGLY YUM이 최종적으로 제안하는 것은 단순한 젤리 스낵이 아니라, 아이의 하루 안에 짧고 선명한 즐거움을 만드는 경험입니다. 좋은 키즈 브랜드는 아이에게만 귀엽게 보이는 것이 아니라, 부모에게도 그 브랜드가 왜 필요한지 납득되어야 합니다. 우리는 위글리염이 아이에게는 재미있는 맛과 식감으로, 부모에게는 밝고 명료한 제품 인상으로 기억되도록 브랜드의 언어를 설계했습니다. 제품의 색, "],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/078b0d78f621c.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/5ab6ac9c9831a.png"]},{"label":"Archive Images","title":"Archive Images","paragraphs":["WIGGLY YUM Brand Project는 아이의 표정과 식감의 반응에서 출발한 키즈 젤리 스낵 브랜딩 작업입니다. 레드와 라임 컬러, 말랑한 로고 리듬, 사과 기반의 상큼한 이미지, 손에 들기 쉬운 스틱형 패키지를 통해 먹는 순간을 밝고 유쾌한 놀이 경험으로 전환했습니다."],"images":["https://cdn.imweb.me/upload/S2023030963558ef55ba8e/c4314da0ed91d.jpeg","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/37bfdaf4ecfe5.jpeg","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/6a85df923aa22.png","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/74050ad4cc6f3.jpeg","https://cdn.imweb.me/upload/S2023030963558ef55ba8e/0fb58115cfbe4.png"]}]} });